import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"索引管理","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. 本機磁碟機（Local Drives）","slug":"_1-本機磁碟機-local-drives","link":"#_1-本機磁碟機-local-drives","children":[]},{"level":2,"title":"2. 網路磁碟機（Network Drives）","slug":"_2-網路磁碟機-network-drives","link":"#_2-網路磁碟機-network-drives","children":[]},{"level":2,"title":"3. WSL（Linux 子系統）","slug":"_3-wsl-linux-子系統","link":"#_3-wsl-linux-子系統","children":[]},{"level":2,"title":"4. 資料夾（Folders）","slug":"_4-資料夾-folders","link":"#_4-資料夾-folders","children":[]},{"level":2,"title":"5. 排除規則（Exclusions）","slug":"_5-排除規則-exclusions","link":"#_5-排除規則-exclusions","children":[]}],"relativePath":"zh-HK/user-guide/settings/index-drives.md","filePath":"zh-HK/user-guide/settings/index-drives.md","lastUpdated":1792595869000}`),a={name:`zh-HK/user-guide/settings/index-drives.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="索引管理" tabindex="-1">索引管理 <a class="header-anchor" href="#索引管理" aria-label="Permalink to “索引管理”">​</a></h1><p>索引設定頁面用於精細化控制 Lertaro 針對本機硬碟、網路儲存、WSL 子系統以及自訂資料夾的索引範圍、重新整理策略與排除規則。頁面頂部包含五個標籤頁：<strong>本機磁碟機</strong>、<strong>網路磁碟機</strong>、<strong>WSL</strong>（偵測到發行版時自動顯示）、<strong>資料夾</strong>與<strong>排除規則</strong>。</p><h2 id="_1-本機磁碟機-local-drives" tabindex="-1">1. 本機磁碟機（Local Drives） <a class="header-anchor" href="#_1-本機磁碟機-local-drives" aria-label="Permalink to “1. 本機磁碟機（Local Drives）”">​</a></h2><ul><li><strong>頂部彙總狀態</strong>：展示當前已索引的實體磁碟機數量與總檔案/資料夾項目數，並提供<strong>重建索引</strong>按鈕觸發所有本機磁碟的全量重建。</li><li><strong>磁碟機列表行</strong>：每個實體分區獨立顯示一行： <ul><li><strong>啟用/禁用核取方塊</strong>：獨立開關該磁碟的索引。</li><li><strong>檔案系統與狀態</strong>：顯示底層檔案系統類型（NTFS、ReFS、FAT32、exFAT 等）、當前狀態與已索引項目數。</li><li><strong>單盤操作</strong>：每行提供獨立的<strong>重建</strong>與<strong>移除</strong>操作；在重建掃描進行時會動態提供<strong>停止</strong>按鈕。</li></ul></li><li><strong>即時監控機制</strong>：NTFS 與 ReFS 卷透過 Windows 系統的 USN 變更記錄檔實現毫秒級增量同步；FAT32 與 exFAT 卷透過檔案系統即時變更事件監聽。</li><li><strong>重建不中斷</strong>：在某個磁碟重建期間，舊索引將繼續回應使用者的搜尋查詢，直到新索引構建完成後一次替換，期間搜尋不會中斷。若重建過程被系統重啟或手動停止中斷，下次會自動從斷點繼續。</li></ul><h2 id="_2-網路磁碟機-network-drives" tabindex="-1">2. 網路磁碟機（Network Drives） <a class="header-anchor" href="#_2-網路磁碟機-network-drives" aria-label="Permalink to “2. 網路磁碟機（Network Drives）”">​</a></h2><ul><li><strong>網路儲存支援</strong>：展示所有已對應的 Windows 網路共用磁碟（SMB / NAS）。</li><li><strong>重新整理模式（Refresh Mode）</strong>：網路儲存缺乏本機 USN 記錄檔，因此支援自訂計劃輪詢策略： <ul><li><strong>手動</strong> —— 僅在按一下「重建索引」時重新掃描。</li><li><strong>每 15 分鐘</strong> —— 高頻協同辦公目錄推薦。</li><li><strong>每小時</strong> —— 均衡型定時掃描。</li><li><strong>每天</strong> —— 靜態封存共用推薦。</li></ul></li><li><strong>符號連結環路保護</strong>：掃描引擎內建了分支祖先路徑棧與符號連結循環偵測演算法，即使 NAS 共用中存在指向父級目錄的軟連結或重新分析點，也能自動攔截死循環，確保索引數量準確不膨脹。</li></ul><h2 id="_3-wsl-linux-子系統" tabindex="-1">3. WSL（Linux 子系統） <a class="header-anchor" href="#_3-wsl-linux-子系統" aria-label="Permalink to “3. WSL（Linux 子系統）”">​</a></h2><p>當且僅當系統偵測到至少安裝了一個 WSL 發行版時，本標籤頁會自動出現：</p><ul><li><strong>自動探測</strong>：自動識別 Ubuntu、Debian、Arch 等已安裝的 WSL 發行版。</li><li><strong>狀態與重新整理</strong>：提供與網路磁碟機完全一致的狀態監控與重新整理模式設定（手動 / 每 15 分鐘 / 每小時 / 每天）。</li><li><strong>零 I/O 搜尋</strong>：搜尋 WSL 檔案時直接查詢記憶體索引樹，完全不喚醒或阻塞 Linux 子系統。</li></ul><h2 id="_4-資料夾-folders" tabindex="-1">4. 資料夾（Folders） <a class="header-anchor" href="#_4-資料夾-folders" aria-label="Permalink to “4. 資料夾（Folders）”">​</a></h2><p>當你不希望索引整個磁碟機或整台 NAS 伺服器，而只想精準收錄特定工作目錄時，可以使用自訂資料夾索引：</p><ul><li><strong>多選新增</strong>：按一下<strong>新增資料夾</strong>按鈕開啟原生選取器，支援按住 <code>Ctrl</code> 或 <code>Shift</code> 一次性批次選取新增多個目錄。</li><li><strong>UNC 路徑支援</strong>：支援直接新增類似 <code>\\\\server\\share\\projects</code> 的區域網路 UNC 共用目錄。</li><li><strong>獨立計劃重新整理</strong>：每個資料夾均擁有獨立的啟用開關、項目計數與重新整理模式下拉框（手動 / 每 15 分鐘 / 每小時 / 每天）。</li></ul><h2 id="_5-排除規則-exclusions" tabindex="-1">5. 排除規則（Exclusions） <a class="header-anchor" href="#_5-排除規則-exclusions" aria-label="Permalink to “5. 排除規則（Exclusions）”">​</a></h2><p>排除規則用於過濾搜尋結果，並限定網路儲存、WSL 與自訂資料夾的走查範圍；它不會停止本機磁碟的索引——本機磁碟區始終整盤走查，所以在這裡寫 <code>E:\\</code> 只會隱藏它的結果。要停掉某塊本機磁碟的索引，請在上方<strong>本機磁碟機</strong>分頁裡關閉它。規則是一張<strong>統一清單</strong>，沒有子分頁：每條規則由比對方式與等級組成，比對方式依寫法自動判定，輸入框會即時顯示「辨識為」。</p><ul><li><strong>完整路徑</strong>：以磁碟機代號（<code>D:\\Cache</code>）、UNC（<code>\\\\server\\share</code>）、環境變數（<code>%ProgramData%</code>、<code>%APPDATA%</code>）或 <code>shell:</code> 虛擬路徑開頭，屏蔽該目錄及其全部子項。</li><li><strong>萬用字元</strong>：其餘寫法一律按萬用字元處理。<code>*</code> 比對單層目錄內的任意字元（<code>*.log</code>），<code>?</code> 比對單一字符，<code>**</code> 跨層級遞迴（<code>**\\node_modules\\**</code>）。不含分隔符的規則依名稱命中任意層級（<code>node_modules</code>、<code>*.tmp</code>）；含分隔符的規則從磁碟機代號根錨定——<code>Listary\\abc</code> 命中 <code>C:\\Listary\\abc</code> 及其子項，但不會命中 <code>D:\\work\\Listary\\abc</code>。</li><li><strong>規則運算式</strong>：兩端用 <code>/</code> 包住，對完整路徑或檔案名稱做隱式部分比對，例如 <code>/^\\./</code> 排除 Linux 式隱藏點檔案，<code>/~\\$/</code> 排除 Office 產生的臨時鎖定檔案。能用萬用字元就別寫規則運算式：每次比對都要解釋執行，更費資源。</li></ul><p><strong>等級</strong>決定怎麼處理：<strong>排除</strong>完全不顯示，<strong>低／正常／高</strong>只影響先後，高優先規則還能勾選置頂，把命中行釘在結果最前。等級有兩種寫法：行右側的下拉式選單，或文字前綴 <code>!</code> 排除、<code>-</code> 低、<code>+</code> 高，不寫是正常；行首加一個反斜槓可把前綴當普通字符。</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>前綴只在<strong>新增</strong>輸入框與<strong>批次編輯</strong>裡剝掉。行內編輯既有規則時文字按字面處理，改等級請用下拉式選單：把 <code>!</code> 寫進萬用字元規則，它就成了路徑裡的字面字符，而 Windows 路徑不含 <code>!</code>，於是這條規則永遠命中不了任何東西，頁面上也不會報錯。</p></div><p>本機磁碟在搜尋時才套用規則；網路磁碟、WSL 與自訂資料夾在建立索引時就跳過排除項目，套用設定後會自動更新。優先順序規則被排除規則涵蓋時，清單上方出現衝突橫幅，被涵蓋的規則不會生效。</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>排除規則支援<strong>單筆新增</strong>與<strong>批次匯入匯出</strong>：按一下<strong>從清單產生</strong>可把現有規則匯出為多行文字，編輯後按一下<strong>套用到清單</strong>即可一次性批次生效。批次文字裡只要有一行無法辨識，整批都不會套用，文字會留在框裡等你修改。</p></div>`,19)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};